from taf.gnb.oam.coam.vdu.utilities.http_client import HttpClient


class AgentLicensedv1HttpClient(HttpClient):
    """ This class provides a client for the Agent v1 API """
    def __init__(self, base_url, connection_alias):
        super(AgentLicensedv1HttpClient, self).__init__(connection_alias)
        self.base_url = base_url + "/api/licensed/v1"

    def reset_vdu(self, timeout, graceful_cell_shutdown=False):
        endpoint = "/vdu/operations/resets"
        headers = {
            "accept": "application/json",
            "content-type": "application/json"
        }
        payload = {
            "gracefulCellShutdown": graceful_cell_shutdown
        }

        return self._send_post_request(endpoint=endpoint, headers=headers, json=payload, timeout=timeout)

    def get_reset_vdu_operation_status(self, operation_id, timeout):
        endpoint = f"/vdu/operations/resets/{operation_id}"
        headers = {
            "accept": "application/json",
        }

        return self._send_get_request(endpoint=endpoint, headers=headers, timeout=timeout)
